CREATE OR REPLACE FUNCTION extensions.grant_pg_graphql_access()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
    if not exists (
        select 1
        from pg_catalog.pg_event_trigger_ddl_commands() ev
        join pg_catalog.pg_extension e on ev.objid = e.oid
        where e.extname = 'pg_graphql'
    ) then
        return;
    end if;

    drop function if exists graphql_public.graphql;
    create or replace function graphql_public.graphql(
        "operationName" text default null,
        query text default null,
        variables jsonb default null,
        extensions jsonb default null
    )
        returns jsonb
        language sql
    as $$
        select graphql.resolve(
            query := query,
            variables := coalesce(variables, '{}'),
            "operationName" := "operationName",
            extensions := extensions
        );
    $$;

    -- Attach the wrapper to the extension so DROP EXTENSION cascades to it,
    -- which in turn triggers set_graphql_placeholder to reinstall the "not enabled" stub.
    alter extension pg_graphql add function graphql_public.graphql(text, text, jsonb, jsonb);

    grant usage on schema graphql to postgres, anon, authenticated, service_role;
    grant execute on function graphql.resolve to postgres, anon, authenticated, service_role;
    grant usage on schema graphql to postgres with grant option;
    grant usage on schema graphql_public to postgres with grant option;
end;
$function$

CREATE OR REPLACE FUNCTION extensions.grant_pg_net_access()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM pg_event_trigger_ddl_commands() AS ev
    JOIN pg_extension AS ext
    ON ev.objid = ext.oid
    WHERE ext.extname = 'pg_net'
  )
  THEN
    IF NOT EXISTS (
      SELECT 1
      FROM pg_roles
      WHERE rolname = 'supabase_functions_admin'
    )
    THEN
      CREATE USER supabase_functions_admin NOINHERIT CREATEROLE LOGIN NOREPLICATION;
    END IF;

    GRANT USAGE ON SCHEMA net TO supabase_functions_admin, postgres, anon, authenticated, service_role;

    IF EXISTS (
      SELECT FROM pg_extension
      WHERE extname = 'pg_net'
      -- all versions in use on existing projects as of 2025-02-20
      -- version 0.12.0 onwards don't need these applied
      AND extversion IN ('0.2', '0.6', '0.7', '0.7.1', '0.8.0', '0.10.0', '0.11.0')
    ) THEN
      ALTER function net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) SECURITY DEFINER;
      ALTER function net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) SECURITY DEFINER;

      ALTER function net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) SET search_path = net;
      ALTER function net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) SET search_path = net;

      REVOKE ALL ON FUNCTION net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) FROM PUBLIC;
      REVOKE ALL ON FUNCTION net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) FROM PUBLIC;

      GRANT EXECUTE ON FUNCTION net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) TO supabase_functions_admin, postgres, anon, authenticated, service_role;
      GRANT EXECUTE ON FUNCTION net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) TO supabase_functions_admin, postgres, anon, authenticated, service_role;
    END IF;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.accept_group_invite(p_membership_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_user_id UUID;
  v_group_id UUID;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Verify this invitation belongs to the current user and is pending
  SELECT group_id INTO v_group_id
  FROM study_group_members
  WHERE id = p_membership_id
    AND user_id = v_user_id
    AND status = 'invited';

  IF v_group_id IS NULL THEN
    RAISE EXCEPTION 'Invitation not found or already processed';
  END IF;

  -- Accept: update status to active, reset joined_at to now
  UPDATE study_group_members
  SET status = 'active', joined_at = NOW()
  WHERE id = p_membership_id;

  -- Automatic notification cleanup: mark the corresponding notification as read
  UPDATE notifications
  SET is_read = true
  WHERE user_id = v_user_id
    AND type = 'group_invite'
    AND metadata->>'membership_id' = p_membership_id::TEXT
    AND is_read = false;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_batch_action_denial(p_actor uuid, p_group_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_role     text;
  v_is_batch boolean;
  v_archived timestamptz;
BEGIN
  SELECT role INTO v_role FROM public.profiles WHERE id = p_actor;
  IF v_role IS NULL OR v_role NOT IN ('admin', 'super_admin') THEN
    RETURN 'not_admin';
  END IF;
  SELECT is_batch_group, archived_at INTO v_is_batch, v_archived FROM public.study_groups WHERE id = p_group_id;
  IF NOT FOUND THEN
    RETURN 'batch_not_found';
  END IF;
  IF v_is_batch IS NOT TRUE THEN
    RETURN 'not_a_batch';
  END IF;
  IF v_archived IS NOT NULL THEN
    RETURN 'batch_archived';
  END IF;
  -- FUTURE (B2B): institution scoping goes here (an 'admin' may only manage batches of their own institution; a
  -- 'super_admin' stays global). Every batch action inherits it automatically.
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_bulk_add_to_batch(p_group_id uuid, p_user_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_actor      uuid := auth.uid();
  v_denial     text;
  v_name       text;
  v_archived   timestamptz;
  v_requested  integer;
  v_not_found  integer;
  v_not_student integer;
  v_not_enrolled integer;
  v_suspended  integer;
  v_eligible   integer;
  v_added      integer;
  v_added_ids  uuid[];
BEGIN
  IF p_user_ids IS NULL OR cardinality(p_user_ids) = 0 THEN
    RAISE EXCEPTION 'Select at least one student';
  END IF;
  IF cardinality(p_user_ids) > 500 THEN
    RAISE EXCEPTION 'Too many students in one call (max 500)';
  END IF;

  v_denial := public.admin_batch_action_denial(v_actor, p_group_id);
  IF v_denial IS NOT NULL THEN
    RAISE EXCEPTION 'Access denied: %', v_denial USING ERRCODE = '42501';
  END IF;

  -- Lock the batch row (same convention as the single-student functions) and re-check it under the lock.
  SELECT name, archived_at INTO v_name, v_archived FROM public.study_groups WHERE id = p_group_id FOR UPDATE;
  IF v_archived IS NOT NULL THEN
    RAISE EXCEPTION 'Access denied: batch_archived' USING ERRCODE = '42501';
  END IF;

  SELECT count(*),
         count(*) FILTER (WHERE reason = 'not_found'),
         count(*) FILTER (WHERE reason = 'not_student'),
         count(*) FILTER (WHERE reason = 'not_enrolled'),
         count(*) FILTER (WHERE reason = 'suspended'),
         count(*) FILTER (WHERE reason IS NULL)
    INTO v_requested, v_not_found, v_not_student, v_not_enrolled, v_suspended, v_eligible
    FROM (
      SELECT i.u AS id,
             CASE
               WHEN p.id IS NULL                               THEN 'not_found'
               WHEN p.role <> 'student'                        THEN 'not_student'
               WHEN p.account_type = 'self_registered'         THEN 'not_enrolled'
               WHEN COALESCE(p.status, 'active') = 'suspended' THEN 'suspended'
               ELSE NULL
             END AS reason
        FROM (SELECT DISTINCT u FROM unnest(p_user_ids) AS u) i
        LEFT JOIN public.profiles p ON p.id = i.u
    ) cls;

  WITH cls AS (
    SELECT i.u AS id,
           CASE
             WHEN p.id IS NULL                               THEN 'not_found'
             WHEN p.role <> 'student'                        THEN 'not_student'
             WHEN p.account_type = 'self_registered'         THEN 'not_enrolled'
             WHEN COALESCE(p.status, 'active') = 'suspended' THEN 'suspended'
             ELSE NULL
           END AS reason
      FROM (SELECT DISTINCT u FROM unnest(p_user_ids) AS u) i
      LEFT JOIN public.profiles p ON p.id = i.u
  ), ups AS (
    INSERT INTO public.study_group_members (group_id, user_id, role, status)
    SELECT p_group_id, c.id, 'member', 'active' FROM cls c WHERE c.reason IS NULL
    ON CONFLICT (group_id, user_id) DO UPDATE
      SET status = 'active', joined_at = NOW()
      WHERE study_group_members.status <> 'active'
    RETURNING user_id
  ), notif AS (
    INSERT INTO public.notifications (user_id, type, title, message, metadata)
    SELECT u.user_id, 'batch_added', 'You''ve been added to ' || v_name,
           'You now have access to this batch''s shared study content.',
           jsonb_build_object('group_id', p_group_id)
    FROM ups u
    RETURNING 1
  )
  SELECT count(*), COALESCE(array_agg(user_id), ARRAY[]::uuid[]) INTO v_added, v_added_ids FROM ups;

  IF v_added > 0 THEN
    INSERT INTO public.admin_audit_log (action, admin_id, target_user_id, details)
    VALUES ('bulk_add_to_batch', v_actor, NULL,
            jsonb_build_object('group_id', p_group_id, 'group_name', v_name, 'requested', v_requested, 'added', v_added,
                               'already_active', v_eligible - v_added,
                               'skipped', jsonb_build_object('not_found', v_not_found, 'not_student', v_not_student,
                                                             'not_enrolled', v_not_enrolled, 'suspended', v_suspended),
                               'user_ids', to_jsonb(v_added_ids[1:200]), 'via', 'admin_bulk_add_to_batch'));
  END IF;

  RETURN jsonb_build_object(
    'requested', v_requested, 'added', v_added, 'already_active', v_eligible - v_added,
    'skipped_not_found', v_not_found, 'skipped_not_student', v_not_student,
    'skipped_not_enrolled', v_not_enrolled, 'skipped_suspended', v_suspended);
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_bulk_resolve_batch_requests(p_action text, p_membership_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_actor      uuid := auth.uid();
  v_requested  integer;
  v_archived   integer;
  v_processed  integer := 0;
  v_user_ids   uuid[] := ARRAY[]::uuid[];
  v_group_ids  uuid[] := ARRAY[]::uuid[];
BEGIN
  IF p_action IS NULL OR p_action NOT IN ('approve', 'reject') THEN
    RAISE EXCEPTION 'Invalid action: %', COALESCE(p_action, 'NULL');
  END IF;
  IF p_membership_ids IS NULL OR cardinality(p_membership_ids) = 0 THEN
    RAISE EXCEPTION 'Select at least one request';
  END IF;
  IF cardinality(p_membership_ids) > 500 THEN
    RAISE EXCEPTION 'Too many requests in one call (max 500)';
  END IF;
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Access denied: not_admin' USING ERRCODE = '42501';
  END IF;

  -- Lock every involved batch in a stable order (no deadlocks between concurrent bulk calls).
  PERFORM 1 FROM public.study_groups g
   WHERE g.id IN (SELECT m.group_id FROM public.study_group_members m WHERE m.id = ANY (p_membership_ids))
   ORDER BY g.id FOR UPDATE;

  SELECT count(DISTINCT x) INTO v_requested FROM unnest(p_membership_ids) AS x;

  -- Pending requests that sit in an archived batch: skipped, counted.
  SELECT count(*) INTO v_archived
    FROM public.study_group_members m
    JOIN public.study_groups g ON g.id = m.group_id
   WHERE m.id = ANY (p_membership_ids) AND m.status = 'requested' AND g.archived_at IS NOT NULL;

  IF p_action = 'approve' THEN
    WITH upd AS (
      UPDATE public.study_group_members m
         SET status = 'active', joined_at = NOW()
        FROM public.study_groups g
       WHERE m.id = ANY (p_membership_ids) AND m.status = 'requested'
         AND g.id = m.group_id AND g.is_batch_group = true AND g.archived_at IS NULL
      RETURNING m.user_id, g.id AS gid, g.name AS gname
    ), notif AS (
      INSERT INTO public.notifications (user_id, type, title, message, metadata)
      SELECT u.user_id, 'batch_approved', 'Your request to join ' || u.gname || ' was approved',
             'You now have access to this batch''s shared study content.',
             jsonb_build_object('group_id', u.gid)
      FROM upd u
      RETURNING 1
    )
    SELECT count(*), COALESCE(array_agg(user_id), ARRAY[]::uuid[]), COALESCE(array_agg(DISTINCT gid), ARRAY[]::uuid[])
      INTO v_processed, v_user_ids, v_group_ids FROM upd;
  ELSE
    WITH del AS (
      DELETE FROM public.study_group_members m
       USING public.study_groups g
       WHERE m.id = ANY (p_membership_ids) AND m.status = 'requested'
         AND g.id = m.group_id AND g.is_batch_group = true AND g.archived_at IS NULL
      RETURNING m.user_id, g.id AS gid
    )
    SELECT count(*), COALESCE(array_agg(user_id), ARRAY[]::uuid[]), COALESCE(array_agg(DISTINCT gid), ARRAY[]::uuid[])
      INTO v_processed, v_user_ids, v_group_ids FROM del;
  END IF;

  IF v_processed > 0 THEN
    INSERT INTO public.admin_audit_log (action, admin_id, target_user_id, details)
    VALUES (CASE WHEN p_action = 'approve' THEN 'bulk_approve_batch_requests' ELSE 'bulk_reject_batch_requests' END,
            v_actor, NULL,
            jsonb_build_object('requested', v_requested, 'processed', v_processed,
                               'skipped_archived', v_archived, 'skipped_resolved', v_requested - v_processed - v_archived,
                               'group_ids', to_jsonb(v_group_ids), 'user_ids', to_jsonb(v_user_ids[1:200]),
                               'via', 'admin_bulk_resolve_batch_requests'));
  END IF;

  RETURN jsonb_build_object('action', p_action, 'requested', v_requested, 'processed', v_processed,
                            'skipped_archived', v_archived, 'skipped_resolved', v_requested - v_processed - v_archived);
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_delete_user_data(p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_denial  text;
  v_name    text;
  v_email   text;
  v_role    text;
  v_notes   integer;
  v_cards   integer;
  v_detached integer;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM profiles WHERE id = auth.uid() AND role = 'super_admin'
  ) THEN
    RAISE EXCEPTION 'Only super_admin can delete user data';
  END IF;

  -- Never yourself, never an admin / super admin account (demote first with admin_change_role).
  v_denial := public.admin_user_action_denial(auth.uid(), p_user_id);
  IF v_denial IS NOT NULL THEN
    RAISE EXCEPTION 'Access denied: %', v_denial USING ERRCODE = '42501';
  END IF;

  SELECT full_name, email, role INTO v_name, v_email, v_role FROM profiles WHERE id = p_user_id;
  SELECT count(*) INTO v_notes FROM notes WHERE user_id = p_user_id;
  SELECT count(*) INTO v_cards FROM flashcards WHERE user_id = p_user_id;
  SELECT count(*) INTO v_detached FROM flashcard_batch_provenance WHERE created_by = p_user_id;

  -- Audit FIRST, while the profile still exists (the foreign key nulls target_user_id afterwards, as before).
  INSERT INTO public.admin_audit_log (action, admin_id, target_user_id, details)
  VALUES ('delete_user', auth.uid(), p_user_id,
          jsonb_build_object('deleted_user_name', v_name, 'deleted_user_email', v_email, 'deleted_user_role', v_role,
                             'deleted_notes_count', v_notes, 'deleted_flashcards_count', v_cards,
                             'total_content_deleted', v_notes + v_cards,
                             'provenance_rows_detached', v_detached,
                             'auth_deletion_status', 'manual_required', 'via', 'admin_delete_user_data'));

  -- The only foreign key to profiles(id) with no delete rule: detach, do not delete, the batch-source history.
  UPDATE flashcard_batch_provenance SET created_by = NULL WHERE created_by = p_user_id;

  DELETE FROM study_group_members WHERE user_id = p_user_id;
  DELETE FROM profile_courses    WHERE user_id = p_user_id;
  DELETE FROM reviews            WHERE user_id = p_user_id;
  DELETE FROM flashcards         WHERE user_id = p_user_id;
  DELETE FROM flashcard_decks    WHERE user_id = p_user_id;
  DELETE FROM notes              WHERE user_id = p_user_id;
  DELETE FROM profiles           WHERE id      = p_user_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.approve_batch_join_request(p_membership_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_group_id    uuid;
  v_user_id     uuid;
  v_name        text;
  v_archived_at timestamptz;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Access denied: admin only';
  END IF;

  SELECT group_id, user_id INTO v_group_id, v_user_id FROM study_group_members WHERE id = p_membership_id;
  IF v_group_id IS NULL THEN
    RAISE EXCEPTION 'Request not found or already resolved';
  END IF;

  SELECT name, archived_at INTO v_name, v_archived_at FROM study_groups WHERE id = v_group_id FOR UPDATE;
  IF v_archived_at IS NOT NULL THEN
    RAISE EXCEPTION 'This batch has been archived';
  END IF;

  UPDATE study_group_members
  SET status = 'active', joined_at = NOW()
  WHERE id = p_membership_id AND status = 'requested';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Request not found or already resolved';
  END IF;

  INSERT INTO public.admin_audit_log (action, admin_id, target_user_id, details)
  VALUES ('approve_batch_join_request', auth.uid(), v_user_id,
          jsonb_build_object('group_id', v_group_id, 'group_name', v_name, 'membership_id', p_membership_id,
                             'via', 'approve_batch_join_request'));

  INSERT INTO public.notifications (user_id, type, title, message, metadata)
  VALUES (v_user_id, 'batch_approved', 'Your request to join ' || v_name || ' was approved',
          'You now have access to this batch''s shared study content.', jsonb_build_object('group_id', v_group_id));
END;
$function$

CREATE OR REPLACE FUNCTION public.archive_batch_group(p_group_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_is_batch    boolean;
  v_archived_at timestamptz;
  v_new_archived_at timestamptz;
  v_report      jsonb;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Access denied: admin only';
  END IF;

  SELECT is_batch_group, archived_at INTO v_is_batch, v_archived_at
  FROM study_groups WHERE id = p_group_id FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Group not found';
  END IF;
  IF NOT v_is_batch THEN
    RAISE EXCEPTION 'Not a batch group';
  END IF;

  IF v_archived_at IS NOT NULL THEN
    RETURN jsonb_build_object('group_id', p_group_id, 'archived_at', v_archived_at, 'already_archived', true);
  END IF;

  v_new_archived_at := clock_timestamp();

  SELECT jsonb_build_object(
    'group', jsonb_build_object(
      'name', sg.name,
      'description', sg.description,
      'batch_course', sg.batch_course,
      'batch_institution', sg.batch_institution
    ),
    'member_count', (
      SELECT COUNT(*) FROM study_group_members WHERE group_id = p_group_id AND status = 'active'
    ),
    'members', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'user_id', s.user_id,
        'full_name', s.full_name,
        'reviews_this_week', s.reviews_this_week,
        'streak_days', s.streak_days,
        'study_time_this_week_seconds', s.study_time_this_week_seconds,
        'last_active_date', s.last_active_date
      ))
      FROM get_batch_group_member_stats(p_group_id) s
    ), '[]'::jsonb)
  ) INTO v_report
  FROM study_groups sg WHERE sg.id = p_group_id;

  INSERT INTO batch_group_archives (group_id, archived_at, archived_by, report)
  VALUES (p_group_id, v_new_archived_at, auth.uid(), v_report);

  UPDATE study_groups
  SET archived_at = v_new_archived_at, archived_by = auth.uid()
  WHERE id = p_group_id;

  UPDATE study_group_members
  SET status = 'closed', closed_at = v_new_archived_at, closed_reason = 'batch_archived'
  WHERE group_id = p_group_id AND status IN ('requested', 'invited');

  RETURN jsonb_build_object('group_id', p_group_id, 'archived_at', v_new_archived_at, 'already_archived', false);
END;
$function$

CREATE OR REPLACE FUNCTION public.assign_professor_to_batch(p_group_id uuid, p_professor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_actor    uuid := auth.uid();
  v_denial   text;
  v_name     text;
  v_archived timestamptz;
  v_pname    text;
  v_prole    text;
  v_pstatus  text;
  v_n        integer;
BEGIN
  v_denial := public.batch_group_access_denial(v_actor, p_group_id, 'manage');
  IF v_denial IS NOT NULL THEN
    RAISE EXCEPTION 'Access denied: %', v_denial USING ERRCODE = '42501';
  END IF;

  -- Lock the batch row and re-check it under the lock (an archive racing this call must win).
  SELECT name, archived_at INTO v_name, v_archived FROM public.study_groups WHERE id = p_group_id FOR UPDATE;
  IF v_archived IS NOT NULL THEN
    RAISE EXCEPTION 'Access denied: batch_archived' USING ERRCODE = '42501';
  END IF;

  SELECT full_name, role, status INTO v_pname, v_prole, v_pstatus FROM public.profiles WHERE id = p_professor_id;
  IF NOT FOUND OR v_prole <> 'professor' OR COALESCE(v_pstatus, 'active') = 'suspended' THEN
    RAISE EXCEPTION 'Target must be an active professor';
  END IF;

  INSERT INTO public.batch_group_professors (group_id, professor_id, assigned_by, assignment_source)
  VALUES (p_group_id, p_professor_id, v_actor, 'admin')
  ON CONFLICT (group_id, professor_id) DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT;

  IF v_n > 0 THEN
    INSERT INTO public.admin_audit_log (action, admin_id, target_user_id, details)
    VALUES ('assign_professor_to_batch', v_actor, p_professor_id,
            jsonb_build_object('group_id', p_group_id, 'group_name', v_name, 'professor_name', v_pname, 'via', 'assign_professor_to_batch'));
  END IF;

  RETURN jsonb_build_object('changed', v_n > 0, 'group_id', p_group_id, 'professor_id', p_professor_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.batch_group_access_denial(p_actor uuid, p_group_id uuid, p_need text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_role     text;
  v_status   text;
  v_is_batch boolean;
  v_archived timestamptz;
BEGIN
  IF p_need IS NULL OR p_need NOT IN ('manage', 'admin_view', 'view') THEN
    RAISE EXCEPTION 'batch_group_access_denial: unknown need %', p_need;
  END IF;
  IF p_actor IS NULL THEN
    RETURN 'not_authenticated';
  END IF;

  SELECT role, status INTO v_role, v_status FROM public.profiles WHERE id = p_actor;
  IF NOT FOUND OR COALESCE(v_status, 'active') = 'suspended' THEN
    RETURN 'account_inactive';
  END IF;

  IF v_role NOT IN ('admin', 'super_admin') THEN
    -- Only the 'view' need can be satisfied by a professor, and only through an explicit assignment to THIS batch.
    IF p_need <> 'view'
       OR v_role <> 'professor'
       OR NOT EXISTS (SELECT 1 FROM public.batch_group_professors bgp WHERE bgp.group_id = p_group_id AND bgp.professor_id = p_actor) THEN
      RETURN 'not_authorized';
    END IF;
  END IF;

  SELECT is_batch_group, archived_at INTO v_is_batch, v_archived FROM public.study_groups WHERE id = p_group_id;
  IF NOT FOUND THEN
    RETURN 'batch_not_found';
  END IF;
  IF v_is_batch IS NOT TRUE THEN
    RETURN 'not_a_batch';
  END IF;
  IF p_need = 'manage' AND v_archived IS NOT NULL THEN
    RETURN 'batch_archived';
  END IF;

  -- FUTURE (B2B): institution scoping goes here, once, for every batch function that calls this helper.
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_batch_group(p_course_level text, p_name text, p_description text DEFAULT ''::text, p_institution text DEFAULT 'More Classes Commerce'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_group_id uuid;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Access denied: admin only';
  END IF;

  INSERT INTO study_groups (name, description, is_batch_group, group_type, batch_course, batch_institution, created_by)
  VALUES (p_name, p_description, true, 'batch', p_course_level, p_institution, auth.uid())
  RETURNING id INTO v_group_id;

  RETURN v_group_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_study_group(p_name text, p_description text DEFAULT NULL::text, p_group_type text DEFAULT 'custom'::text, p_linked_course text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_group_id UUID;
  v_user_id  UUID;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF p_group_type NOT IN ('system_course', 'custom') THEN
    RAISE EXCEPTION 'Invalid group_type: %. Must be system_course or custom.', p_group_type;
  END IF;

  INSERT INTO study_groups (name, description, created_by, group_type, linked_course)
  VALUES (p_name, p_description, v_user_id, p_group_type, p_linked_course)
  RETURNING id INTO v_group_id;

  INSERT INTO study_group_members (group_id, user_id, role, status)
  VALUES (v_group_id, v_user_id, 'admin', 'active');

  RETURN v_group_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.enroll_user_in_batch_group(p_user_id uuid, p_group_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_is_batch    boolean;
  v_archived_at timestamptz;
  v_name        text;
  v_changed     integer;
  v_target_role text;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Access denied: admin only';
  END IF;

  SELECT is_batch_group, archived_at, name INTO v_is_batch, v_archived_at, v_name
  FROM study_groups WHERE id = p_group_id FOR UPDATE;

  IF NOT FOUND OR NOT v_is_batch THEN
    RAISE EXCEPTION 'Not a batch group';
  END IF;
  IF v_archived_at IS NOT NULL THEN
    RAISE EXCEPTION 'This batch has been archived';
  END IF;

  -- Sprint 8.8.5d: batch membership is a student concept (professor access = assignment); enforced here, not only in the UI.
  SELECT role INTO v_target_role FROM profiles WHERE id = p_user_id;
  IF v_target_role IS DISTINCT FROM 'student' THEN
    RAISE EXCEPTION 'Only students can be added to a batch';
  END IF;

  INSERT INTO study_group_members (group_id, user_id, role, status)
  VALUES (p_group_id, p_user_id, 'member', 'active')
  ON CONFLICT (group_id, user_id) DO UPDATE
    SET status = 'active', joined_at = NOW()
    WHERE study_group_members.status <> 'active';
  GET DIAGNOSTICS v_changed = ROW_COUNT;

  -- Audit + notify only when membership newly became active (an already-active member is left untouched).
  IF v_changed > 0 THEN
    INSERT INTO public.admin_audit_log (action, admin_id, target_user_id, details)
    VALUES ('add_to_batch', auth.uid(), p_user_id,
            jsonb_build_object('group_id', p_group_id, 'group_name', v_name, 'via', 'enroll_user_in_batch_group'));

    INSERT INTO public.notifications (user_id, type, title, message, metadata)
    VALUES (p_user_id, 'batch_added', 'You''ve been added to ' || v_name,
            'You now have access to this batch''s shared study content.', jsonb_build_object('group_id', p_group_id));
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_batch_group_archive(p_group_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_denial      text;
  v_archived_at timestamptz;
  v_report      jsonb;
BEGIN
  v_denial := public.batch_group_access_denial(auth.uid(), p_group_id, 'view');
  IF v_denial IS NOT NULL THEN
    IF v_denial IN ('batch_not_found', 'not_a_batch') THEN
      RAISE EXCEPTION 'Not a batch group';
    END IF;
    RAISE EXCEPTION 'Access denied';
  END IF;

  SELECT archived_at INTO v_archived_at FROM study_groups WHERE id = p_group_id;
  IF v_archived_at IS NULL THEN
    RAISE EXCEPTION 'Batch is not archived';
  END IF;

  SELECT report INTO v_report
  FROM batch_group_archives
  WHERE group_id = p_group_id AND archived_at = v_archived_at;

  IF v_report IS NULL THEN
    RAISE EXCEPTION 'Archive snapshot not found';
  END IF;

  RETURN jsonb_build_object('archived_at', v_archived_at, 'report', v_report);
END;
$function$

CREATE OR REPLACE FUNCTION public.get_group_preview(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_group_id      UUID;
  v_archived_at   TIMESTAMPTZ;
  v_is_batch      BOOLEAN;
  v_group         JSONB;
  v_stats         JSONB;
  v_viewer_status TEXT;
BEGIN
  SELECT id, archived_at, is_batch_group INTO v_group_id, v_archived_at, v_is_batch
  FROM study_groups
  WHERE invite_token = p_token;

  IF v_group_id IS NULL THEN
    RETURN jsonb_build_object('group', NULL, 'stats', NULL);
  END IF;

  IF auth.uid() IS NOT NULL THEN
    SELECT status INTO v_viewer_status
    FROM study_group_members
    WHERE group_id = v_group_id AND user_id = auth.uid();
  END IF;

  SELECT jsonb_build_object(
    'id',           sg.id,
    'name',         sg.name,
    'description',  sg.description,
    'member_count', (
      SELECT COUNT(*) FROM study_group_members
      WHERE group_id = sg.id AND status = 'active'
    ),
    'group_type',        sg.group_type,
    'is_batch_group',    sg.is_batch_group,
    'batch_course',      sg.batch_course,
    'batch_institution', sg.batch_institution,
    'viewer_status',     v_viewer_status,
    'archived_at',       sg.archived_at
  ) INTO v_group
  FROM study_groups sg
  WHERE sg.id = v_group_id;

  IF v_is_batch AND v_archived_at IS NOT NULL THEN
    RETURN jsonb_build_object('group', v_group, 'stats', NULL);
  END IF;

  -- stats block unchanged from the live version
  SELECT jsonb_build_object(
    'avg_streak',           0,
    'total_weekly_reviews', COALESCE(SUM(weekly.cnt), 0),
    'top_badge_name',       (
      SELECT bd.name
      FROM user_badges ub
      JOIN badge_definitions bd ON bd.id = ub.badge_id
      WHERE ub.user_id IN (
        SELECT user_id FROM study_group_members
        WHERE group_id = v_group_id AND status = 'active'
      )
      GROUP BY bd.name
      ORDER BY COUNT(*) DESC
      LIMIT 1
    )
  ) INTO v_stats
  FROM study_group_members sgm
  LEFT JOIN LATERAL (
    SELECT COUNT(*) AS cnt
    FROM reviews r
    WHERE r.user_id = sgm.user_id
      AND r.created_at >= NOW() - INTERVAL '7 days'
  ) weekly ON true
  WHERE sgm.group_id = v_group_id
    AND sgm.status = 'active';

  RETURN jsonb_build_object('group', v_group, 'stats', v_stats);
END;
$function$
